      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n9/2) 20~60세 여성) 미용/에스테틱 이용자 좌담회\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.08.03. 14:04\n조회 190\n구독\n9/2) 20~60세 남/여) 미용/에스테틱 이용자 좌담회\n►대상 : 현재 미용 피부과 또는 피부과 중심 에스테틱에서 아래 4개 분야의 서비스를 1개 이상 받은 성인 20~60세 남/여대상\n1.주사 시술(Injectables): 보톡스, 필러, 바이오자극제(biostimulators) 시술자\n2.바디 컨투어링(Body Contouring): 비침습 지방 감소, 피부 탄력 강화, 근육 자극 시술자\n3.모발 복원(Hair Restoration): 처방용 외용제 및 경구약, PRP(자가혈소판치료), 모발이식 수술자\n4.치료용 레이저(Therapeutic Lasers): 피부 재생(리서페이싱), 색소 교정, 혈관 및 주사(rosacea) 치료 시술자\n►일정 : 1그룹 : 20~44세 여성 ->9월 2일(수) 오후 6시 15분\n2그룹 : 45~60세 여성 ->9월 2일(수) 오후 4시\n3그룹 : 20~60세 남성 ->9월 2일(수) 저녁 8시\n►소요 시간: 1시간 15분\n►장소 : 6호선 상수역 부근\n►사례비 : 컨택시\n0) 구분 (1,2,3,4)\n1) 이름\n2) 연령(생년월일)\n3) 직업(회사명 및 부서명)\n4) 결혼 유무\n5) 가족 인원수\n6) 거주지\n7) 가구 소득\n8) 현재 본인이 받은 시술명 및 이용 횟수\n(1.보톡스 -> 2026년 1월, 4월, 6월 ( 3회 이상~정기적 관리) /3.모발이식 수술-> 2026년 5월( 1~2회 비정기) /4.흉터,모공,여드름,홍조..->2026년 3월,6월, 9월 (3회 이상 정기적 관리)\n9) 현재 본인이 받은 병원명 및 사용 금액 (1.보톡스 ->차앤박피부과 /3회 30만원)\n10) 피부 유형 (지성, 민감성, 건성, 복합성)\n11) 피부 고민 (아토피, 건선, 습진, 홍조, 가려움증, 여드름, 뾰두라지, 탈모…. 등)\n12) 연락처\n**현재 이용하는 피부과 비용 및 사진(영수증) 요청할 수 있음**\nhttps://forms.gle/bfybpuXkrE9u1JMu8\n좋아요\n0\n송파구에서 핫한 진짜 동네 이야기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.08.03. 16:20 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n8/6) 50-64세 남성) 홍삼 관련좌담회\n좌담회알바좌담회카페\n26.08.03.\n댓글\n1\n9/2) 20~60세 여성) 미용/에스테틱 이용자 좌담회\n좌담회알바좌담회카페\n26.08.03.\n댓글\n1\n9/2) 20~60세 남성) 미용/에스테틱 이용자 좌담회\n좌담회알바좌담회카페\n26.08.03.\n댓글\n1\n고유링크) 급급급) 만18~24세 여성) 생성형 AI 온라인 커뮤니티 조사\n좌담회알바좌담회카페\n26.08.03.\n댓글\n1\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
